class Cache:
 def __init__(self,capacity):
  if type(capacity)is not int or capacity<=0:raise ValueError()
  self.capacity=capacity;self.entries={}
 def get(self,key):
  value=self.entries.pop(key);self.entries[key]=value;return value
 def put(self,key,value):
  self.entries.pop(key,None);self.entries[key]=value
  if len(self.entries)>self.capacity:self.entries.pop(next(iter(self.entries)))

