import json,tempfile,os
from pathlib import Path
def normalize_number(value):
 if type(value)is float and value.is_integer():return int(value)
 if type(value)is list:return [normalize_number(x)for x in value]
 if type(value)is dict:return {k:normalize_number(v)for k,v in value.items()}
 return value
def solve(path,value):
 payload=json.dumps(normalize_number(value),allow_nan=False,indent=2).encode('utf-8');target=Path(path);name=None
 try:
  with tempfile.NamedTemporaryFile(mode='wb',dir=target.parent,delete=False)as temporary:
   name=temporary.name;temporary.write(payload)
  Path(name).replace(target)
 finally:
  if name is not None:
   try:os.unlink(name)
   except FileNotFoundError:pass
